return [{
  json: {
    delivery_payloads: [{
      alert_id: 'TEST:NTFY:SENDER',
      subscriber_id: 'TEST_GIO',
      subscriber_name: 'Test Gio',
      ntfy_topic: 'test-citymanager-gio',
      title: 'City Manager OS - ntfy Test',
      message: 'Central ntfy sender is working.',
      priority: 3,
      tags: ['white_check_mark', 'test'],
      click: '',
      matched_watch_ids: ['TEST_W_TOWN'],
      match_reasons: ['Manual ntfy sender test']
    }]
  }
}];

const input = $input.first().json;

let payloads = [];

if (Array.isArray(input.delivery_payloads)) {
  payloads = input.delivery_payloads;
} else if (input.ntfy_topic) {
  payloads = [input];
}

if (!payloads.length) {
  throw new Error('No delivery_payloads or single ntfy delivery payload found.');
}

const NTFY_BASE_URL = 'http://100.94.203.47:8080';

return payloads.map((payload) => {
  if (!payload.ntfy_topic) {
    throw new Error(`Delivery payload is missing ntfy_topic for subscriber ${payload.subscriber_id || 'unknown'}`);
  }

  const priority = Math.max(1, Math.min(5, Number(payload.priority) || 3));
  const tags = Array.isArray(payload.tags) ? payload.tags : [];

  const ntfyBody = {
    topic: payload.ntfy_topic,
    title: payload.title || 'City Manager OS',
    message: payload.message || '',
    priority,
    tags
  };

  if (payload.click) {
    ntfyBody.click = payload.click;
  }

  return {
    json: {
      ...payload,
      ntfy_base_url: NTFY_BASE_URL,
      ntfy_body: ntfyBody
    }
  };
});

const responses = $input.all();
const requests = $('Prepare ntfy Requests').all();

return responses.map((item, index) => {
  const response = item.json;
  const request = requests[index]?.json || {};

  return {
    json: {
      sent: Boolean(response.id) && (response.event === 'message' || !response.event),
      alert_id: request.alert_id || null,
      subscriber_id: request.subscriber_id || null,
      subscriber_name: request.subscriber_name || null,
      ntfy_topic: request.ntfy_topic || response.topic || null,
      matched_watch_ids: request.matched_watch_ids || [],
      match_reasons: request.match_reasons || [],
      ntfy_message_id: response.id || null,
      ntfy_event: response.event || null,
      ntfy_time: response.time || null,
      ntfy_response: response
    }
  };
});
